                    cur_in = row[0]
                if len(row) > 1:
                    cur_reset = row[1]

        # global rule: reset is synchronous; update_during_reset=false for B-D means they hold
        if cur_reset == 1:
            if state == 0:  # A updates during reset (stays A)
                next_state = 0
            else:
                next_state = state
        else:
            # normal transitions
            if state == 0:  # A
                next_state = 0 if cur_in == 0 else 1
            elif state == 1:  # B
                next_state = 2 if cur_in == 0 else 1
            elif state == 2:  # C
                next_state = 0 if cur_in == 0 else 3
            elif state == 3:  # D
                next_state = 2 if cur_in == 0 else 1
            else:
                next_state = 0
        state = next_state

        # Moore outputs based on new state
        if state == 0:  # out_A
            out = 0
        elif state == 1:  # out_B
            out = 0
        elif state == 2:  # out_C
